<template>
  <div class="mt-5">
    <form @submit="transformExcelFileToDynamicArchitecture">
            <div class="d-inlineflex">
              <input class="form-control" type="file" :v-model="file" @change="onFileChange">
              <input class="ms-3 btn btn-secondary" type="submit" value="Generate Architecture" :disabled="file == null">
            </div>
          </form>
    <!-- <div class="archContainer">
      <ArchitectureItem :archObject="JSON.stringify(test)" />
    </div> -->
    <div class="archContainer" v-if="result != null">
      <div class="filterContainer">
        <div style="gap: 15px 45px">
            <div class="searchContainer">
              <input class="form-control" type="text" v-model="searchText" @change="search" />
            </div>
          <div class="d-flex align-items-center">
            <div>Display:</div>
            <select class="form-control autoWidth pointer ms-2" v-model="selectedDisplayOption" @change="filterElementsByFilter">
              <option v-for="kOption in Object.keys(displayOptions)" :key="kOption" :value="displayOptions[kOption].id">{{ displayOptions[kOption].label }}</option>
            </select>
          </div>
          
          <button class="btn btn-danger" style="min-width: 115px;" @click="openWholeArch()">Open all</button>
        </div>
      </div>
      <div v-if="searchResult !== false">
        <div class="small opacity-75 text-danger" v-if="searchResult.length == 0">
          No matches found for this search...
        </div>
        <div class="searchResultsContainer" v-else>
          <div>
            <div>Search Results:</div>
            <div></div>
          </div>
          <ul class="text-start">
            <li v-for="item, index in searchResult" :key="index">
              <a :href="item.link" target="_blank" v-if="item.type == itemTypes.file">{{ item.path }} ***(file)***</a>
              <div v-else>{{ item.path }} ***({{ item.type == itemTypes.folder ? "folder" : "empty folder" }})***</div>
            </li>
          </ul>
        </div>
      </div>
      <div v-if="displayArch">
        <ArchitectureItem :archObject="finalResult" :mainArchitectureLevel="true" @mainCompFullyLoaded="print('mainCompFullyLoaded')" @componentFullyLoaded="setUpFoldersAndFilesIds" v-if="finalResult != null" />
      </div>
    </div>
  </div>
</template>

<script>
import { read, utils } from "xlsx";
import ArchitectureItem from '@/components/ArchitectureItem.vue';

export default {
  name: 'ReadExcel',
  components: {
    ArchitectureItem
  },
  data() {
    return {
      file: null,
      result: null,
      finalResult: null,
      archLoaded: false,
      displayArch: true,
      idList: [],

      itemTypes: {
        mainLevel: -2,
        unknown: -1,
        folder: 0,
        emptyFolder: 1,
        file: 2,
      },
      searchText: "",
      searchTextBeingFixed: false,
      searchResult: false,

      displayOptions: {
        all: {
          id: 0,
          label: "All",
        },
        emptyFolders: {
          id: 1,
          label: "Empty folders",
        },
        non_emptyFolders: {
          id: 2,
          label: "Non-empty folders",
        },
        // onlyFiles: {
        //   id: 3,
        //   label: "Only files",
        // },
      },
      selectedDisplayOption: 0,
    }
  },
  methods: {
    onFileChange(e) {
      event.preventDefault();
      var files = e.target.files || e.dataTransfer.files;
      if (!files.length)
        return;
      this.file = files[0];
    },
    readExcelFile(callback) {
      const file = this.file
      const reader = new FileReader();

      reader.onload = function(e) {
        const data = e.target.result;
        const workbook = read(data, {
          type: 'binary'
        });
        if(workbook != null) {
          callback(workbook);
        }
      }

      reader.onerror = function(ex) {
        console.log(ex);
      };

      reader.readAsBinaryString(file);
    },
    getSharePointArchitecutre(workbook) {
      const sheetData = workbook.Sheets[workbook.SheetNames[0]];
      const range = utils.decode_range(sheetData['!ref']);

      let nameCol = 0;
      let pathCol = 0;
      let itemTypeCol = 0;
      let i = 0;
      while(i < 10) {
        const cellValue = sheetData[utils.encode_cell({r: 0, c: i})];
        if(cellValue) {
            if(cellValue.v.toLowerCase() == "name") {
              nameCol = i;
            };
            if(cellValue.v.toLowerCase() == "path") {
              pathCol = i;
            };
            if(cellValue.v.toLowerCase() == "item type") {
              itemTypeCol = i;
            };
        }
        i++;
      }

      const result = {content: {}, type: this.itemTypes.mainLevel};
      const mainPathCell = sheetData[utils.encode_cell({r: 1, c: pathCol})];
      const mainPath = mainPathCell.v.split("/").filter(x => x.trim().length > 0);
      i = 0;
      while(i < mainPath.length) {
        const pathToEval = mainPath.slice(0, i);
        const stringToEval = 'result.content' + (pathToEval.length > 0 ? '["' : '') + pathToEval.join('"].content["') + (pathToEval.length > 0 ? '"].content' : '');
        eval(stringToEval + '["' + mainPath[i] + '"] = {content: {}, type: "' + this.itemTypes.folder + '"}');
        i++;
      }

      for (var rowNum = range.s.r + 1; rowNum <= range.e.r; rowNum++) {
        let print = false;
        const pathCell = sheetData[utils.encode_cell({r: rowNum, c: pathCol})];
        const path = pathCell.v.split("/").filter(x => x.trim().length > 0);
        
        // Evaluates if path is missing. This usually happens when folder has date name, excel read is at number, changing the name. TODO
        i = 0;
        let missingPath = "";
        while(i < path.length) {
          const pathToEval = path.slice(0, i);
          const stringToEval = 'result.content' + (pathToEval.length > 0 ? '["' : '') + pathToEval.join('"].content["') + (pathToEval.length > 0 ? '"].content' : '') + '["' + path[i] + '"]';
          if(!eval(stringToEval)) {
            missingPath = stringToEval.substring(6);
            eval(stringToEval + ' = {content: {}, type: "' + this.itemTypes.folder + '"}');
            print = true;
          }
          i++;
        }

        const cell = sheetData[utils.encode_cell({r: rowNum, c: nameCol})];
        const itemLink = cell.l.Target;
        const value = String(cell.v);
        let stringToEval = 'result.content["' + path.join('"].content["') + '"].content';// + "['" + sheetData[utils.encode_cell({r: rowNum, c: nameCol})].v + "']";
        let itemType = this.itemTypes.unknown;
        if(sheetData[utils.encode_cell({r: rowNum, c: itemTypeCol})].v == "Folder") {
          itemType = this.itemTypes.folder;
        } else if(sheetData[utils.encode_cell({r: rowNum, c: itemTypeCol})].v == "Item") {
          itemType = this.itemTypes.file;
        }
        stringToEval += '["' + value + '"] = {' + (itemType != this.itemTypes.file ? 'content: {}, ' : '') + 'type: "' + itemType + '",' + 'link: "' + itemLink + '"}';
        if(print) {
          console.log(missingPath)
        }
        eval(stringToEval);
      }

      this.result = result;
    },
    readExcelCallback(workbook) {
      this.getSharePointArchitecutre(workbook);
    },
    transformExcelFileToDynamicArchitecture() {
      this.readExcelFile(this.readExcelCallback);
    },
    toggleFolder(id, forceOpen = false, forceClose = false) {
      const folderIconEl = document.querySelector("#folderItem" + id).childNodes[0];
      const folderContentEl = document.querySelector("#folderContent" + id);
      if(folderIconEl.classList.contains("icon-folder") && !forceClose) {
        folderIconEl.classList.add("icon-folder-opened");
        folderIconEl.classList.remove("icon-folder");

        folderContentEl.classList.remove("hidden");
      } else if(folderIconEl.classList.contains("icon-folder-opened") && !forceOpen) {
        folderIconEl.classList.add("icon-folder");
        folderIconEl.classList.remove("icon-folder-opened");

        folderContentEl.classList.add("hidden");
        Array.from(folderContentEl.childNodes[0].childNodes)
        .filter(x => x.classList.contains("archElement"))
        .filter(x => x.dataset.type != this.itemTypes.file)
        .forEach(x => {
          const childFolderFileContainerEl = Array.from(x.childNodes[0].childNodes).filter(x => x.classList.contains("folderFileContainer"))[0];
          if(childFolderFileContainerEl) {
            const elId = String(childFolderFileContainerEl.id).replace("folderFileContainer", "");
            this.toggleFolder(elId, false, true);
          }
        });
      }
      
      if(folderIconEl.classList.contains("icon-folder-empty-folder") && !forceClose) {
        folderIconEl.classList.add("icon-folder-empty-folder-opened");
        folderIconEl.classList.remove("icon-folder-empty-folder");

        folderContentEl.classList.remove("hidden");
      } else if(folderIconEl.classList.contains("icon-folder-empty-folder-opened") && !forceOpen) {
        folderIconEl.classList.add("icon-folder-empty-folder");
        folderIconEl.classList.remove("icon-folder-empty-folder-opened");

        folderContentEl.classList.add("hidden");
        Array.from(folderContentEl.childNodes[0].childNodes)
        .filter(x => x.classList.contains("archElement"))
        .filter(x => x.dataset.type != this.itemTypes.file)
        .forEach(x => {
          const childFolderFileContainerEl = Array.from(x.childNodes[0].childNodes).filter(x => x.classList.contains("folderFileContainer"))[0];
          if(childFolderFileContainerEl) {
            const elId = String(childFolderFileContainerEl.id).replace("folderFileContainer", "");
            this.toggleFolder(elId, false, true);
          }
        });
      }
    },
    setUpFoldersAndFilesIds() {
      const idList = [];
      document.querySelectorAll(".folderFileContainer").forEach((x, i) => {
        x.id = "folderFileContainer" + i;
        x.childNodes.forEach(y => {
          if(y.classList.contains("folderItem")) {
            y.id = "folderItem" + i;
            y.onclick = () => {
              this.toggleFolder(i);
            };
            idList.push(i);
          } else if(y.classList.contains("folderContent")) {
            y.id = "folderContent" + i;
          }
        })
      });
      this.idList = idList;
    },
    findPathFromFileOrFolderName(str, pathsArrResult = [], data = this.finalResult.content, mainPath = []) {
      str = str.toLowerCase();
      Object.keys(data).forEach(x => {
        x = String(x);
        const currentPath = [...mainPath, x];
        if(x.toLowerCase().match(str)) {
          const itemType = data[x].type;
          pathsArrResult.push({
            path: currentPath.join("/"),
            type: itemType,
            link: data[x].link,
          });
        }
        if(data[x].content) {
          return this.findPathFromFileOrFolderName(str, pathsArrResult, data[x].content, currentPath);
        }
      });
      return pathsArrResult;
    },
    search() {
      if(this.searchText.trim().length != 0) {
        this.searchResult = this.findPathFromFileOrFolderName(this.searchText.toLowerCase());
      } else {
        this.searchResult = false;
      }
    },
    openWholeArch() {
      this.idList.forEach(x => {
        this.toggleFolder(x, true);
      })
    },
    setFinalResult() {
      const resultCopy = JSON.parse(JSON.stringify(this.result));
      const checkResultArr = this.addExtraDataAndFilter(resultCopy);
      // console.log(checkResultArr);
      this.finalResult = checkResultArr[0];
    },
    addExtraDataAndFilter(obj) {
      let hasFiles = false;
      let hasEmpty = false;

      if(obj.hasOwnProperty("type")) {
        if(obj.type == this.itemTypes.file) {
          return [obj, true, false];
        }
      }

      if(obj.hasOwnProperty("content")) {
        if(Object.keys(obj.content).length == 0) {
          hasEmpty = true;
          obj.empty = true;
          obj.type = this.itemTypes.emptyFolder;
        }
        Object.keys(obj.content).forEach(k => {
          const checkResultArr = this.addExtraDataAndFilter(obj.content[k]);
          const hasFilesCheck = checkResultArr[1];
          const hasEmptyCheck = checkResultArr[2];
          obj.content[k] = checkResultArr[0];
          if(hasFilesCheck) {
            if(!hasFiles) {
              hasFiles = true;
            }
          }
          if(hasEmptyCheck) {
            if(!hasEmpty) {
              hasEmpty = true;
            }
          }
          // if(k.trim().toLocaleLowerCase() == "01 - delivery documentation") {
          //   console.log(hasFilesCheck, hasEmptyCheck, obj)
          //   console.log("this.selectedDisplayOption == this.displayOptions.non_emptyFolders", this.selectedDisplayOption == this.displayOptions.non_emptyFolders.id)
          //   console.log("!hasFilesCheck", !hasFilesCheck)
          // }
          if(this.selectedDisplayOption != this.displayOptions.all.id) {
            if(this.selectedDisplayOption == this.displayOptions.emptyFolders.id && !hasEmptyCheck) {
              delete obj.content[k];
            }
            else if(this.selectedDisplayOption == this.displayOptions.non_emptyFolders.id && !hasFilesCheck) {
              delete obj.content[k];
            }
          }
        });
      }

      obj.hasFiles = hasFiles;
      obj.hasEmpty = hasEmpty;
      return [obj, hasFiles, hasEmpty];
    },
    filterElementsByFilter() {
      document.querySelectorAll(".archElement").forEach(x => {
        if(this.selectedDisplayOption == this.displayOptions.all.id) {
          x.classList.remove("hidden");
        } else if(this.selectedDisplayOption == this.displayOptions.emptyFolders.id) {
          if(x.dataset.hasEmpty == 1) {
            x.classList.remove("hidden");
          } else if(x.dataset.hasEmpty == 0 || x.dataset.type == this.itemTypes.file) {
            x.classList.add("hidden");
          }
        } else if(this.selectedDisplayOption == this.displayOptions.non_emptyFolders.id) {
          if(x.dataset.hasFiles == 1 || x.dataset.type == this.itemTypes.file) {
            x.classList.remove("hidden");
          } else if(x.dataset.hasFiles == 0) {
            x.classList.add("hidden");
          }
        }
      });
    },
    print(text) {
      console.log(text);
    }
  },
  watch: {
    searchText(val) {
      let valueInProgress = this.searchText;
      valueInProgress = val.trim();
      if(val.substr(val.length-1) == " ") {
        valueInProgress += " ";
      }
      this.searchTextBeingFixed = false;
      if(this.searchText != valueInProgress) {
        this.searchTextBeingFixed = true;
        this.searchText = valueInProgress;
      }
      if(!this.searchTextBeingFixed) {
        ;
      }
    },
    result() {
      this.setFinalResult();
    },
  }
}
</script>

